				\usepackage{amssymb} 
				\usepackage{amsbsy}
				\usepackage{mathrsfs}
				\usepackage{upgreek}
				\setlength{\oddsidemargin}{-69pt}
				\begin{document}$$\:\text{S}\text{I}=\:\frac{\text{C}\text{C}50\:\left(\text{W}\text{I}38\:\text{c}\text{e}\text{l}\text{l}\text{s}\right)}{\text{I}\text{C}50\left(\text{A}549\:\text{c}\text{e}\text{l}\text{l}\text{s}\right)}.$$\end{document}
